Tiêu chuẩn IEEE dành cho SystemVerilog—Ngôn ngữ thiết kế, mô tả và kiểm thử phần cứng hợp nhất

nettype real realNet;
endpackage : NetsPkg

<tệp driver.svr>
module driver
  import NetsPkg::*;
  #(parameter int delay = 30,
        int iterations = 256)
   (output realNet out[0:1]);
  timeunit 1ns / 1ps;
  real outR[1:0];
  assign out = outR;
  initial begin
    outR[0] = 0.0;
    outR[1] = 3.3;
    for (int i = 0; i < iterations; i++) begin
      #delay outR[0] += 0.2;
             outR[1] -= 0.2;
    end
  end
endmodule : driver

<tệp driver.sv>
module driver #(parameter int delay = 30,
                int iterations = 256)
              (output wire logic out[0:1]);
  timeunit 1ns / 1ps;
  logic [0:1] outvar;

  assign out[0] = outvar[0];
  assign out[1] = outvar[1];

  initial begin
    outvar = '0;
    for (int i = 0; i < iterations; i++)
      #delay outvar++;
  end
endmodule : driver

<tệp cmp.svr>
module cmp
  import NetsPkg::*;
  #(parameter real hyst = 0.65)
   (input realNet inA[0:1],
    input logic rst,
    output logic out);
  timeunit 1ns / 1ps;
  real updatePeriod = 100.0;

  initial out = 1'b0;

  always #updatePeriod begin
    if (rst) out <= 1'b0;
    else if (inA[0] > inA[1]) out <= 1'b1;
    else if (inA[0] < inA[1] - hyst) out <= 1'b0;
  end
endmodule : cmp

IEEE Std 1800-2023
Tiêu chuẩn IEEE cho SystemVerilog—Ngôn ngữ Thiết kế, Tả thực và Kiểm thử Phần cứng Hợp nhất

Như đã mô tả trong 6.6.8, một mạng `interconnect` bị giới hạn về mặt khai báo và sử dụng. Dưới đây là một số ví dụ về khai báo mạng `interconnect` hợp lệ và không hợp lệ:

interconnect w1;                     // hợp lệ
interconnect [3:0] w2;               // hợp lệ
interconnect [3:0] w3 [1:0];         // hợp lệ
interconnect logic [3:0] w4;         // không hợp lệ - đã chỉ định kiểu dữ liệu
interconnect #(1,2,3) w5;            // không hợp lệ - chỉ cho phép một độ trễ
assign w1 = 1;                       // không hợp lệ - không được phép trong phép gán liên tục
initial $display(w1);                // không hợp lệ - không được phép trong ngữ cảnh thủ tục

6.7.2 Khai báo mạng với các kiểu mạng do người dùng tự định nghĩa (user-defined nettypes)

Một mạng với kiểu `nettype` do người dùng tự định nghĩa cho phép người dùng mô tả các giá trị trừu tượng tổng quát hơn cho một dây nối (wire). Một mạng được khai báo với một `nettype` sẽ sử dụng kiểu dữ liệu và bất kỳ hàm phân giải nào gắn liền với `nettype` đó.

// một nettype wT chưa phân giải có kiểu dữ liệu là T
// Tham khảo ví dụ trong 6.6.7 cho khai báo của kiểu dữ liệu T
nettype T wT;

// một nettype wTsum có kiểu dữ liệu là T và hàm phân giải là Tsum
// Tham khảo ví dụ trong 6.6.7 cho khai báo của Tsum
nettype T wTsum with Tsum;

// một mạng thuộc kiểu nettype chưa phân giải wT
wT w1;

// một mảng các mạng, mỗi phần tử mạng thuộc kiểu nettype chưa phân giải wT
wT w2[8];

// một mạng thuộc kiểu nettype đã phân giải wTsum và hàm phân giải Tsum
wTsum w3;

// một mảng các mạng, mỗi phần tử mạng thuộc kiểu nettype đã phân giải wTsum
wTsum w4[8];

